class Solution:
    def maximumLength(self, s: str) -> int:
        max_length = -1
        for i in range(len(s)):
            for j in range(i+2, len(s)+1):
                sub = s[i:j]
                if len(set(sub)) == 1 and len(sub) >= 3:
                    max_length = max(max_length, len(sub))
        return max_length
